"""
status_page.py — صفحه‌ی وضعیتِ پنل مدیر مدرسه (قطعی / خاموش / دسترسی مسدود)

ظاهرِ این صفحه دقیقاً همان صفحه‌ی بارگذاری/خطای پنل اصلیِ تلگرام (webapp/) است:
همان لوگوی «چست منیجمنت فورس / چست سیکیورتی فورس»، همان اندازه‌ی ۱۲۰ پیکسل با
گوشه‌های خمیده‌ی ۲۸ پیکسل و بدون قاب، همان انیمیشنِ شناورِ floaty، همان پس‌زمینه و رنگ‌ها.
لوگو به‌صورت data-URI داخلِ خودِ صفحه است تا وقتی پنل خاموش است و فایل‌های
/principal-assets/ جواب نمی‌دهند هم نمایش داده شود.
"""
import html as _html

LOGO_DATA_URI = "data:image/webp;base64,"

_STYLE = """
*{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent}
html,body{height:100%}
body{
  background:radial-gradient(circle at 50% -10%,#1c2444 0%,#0e1220 60%);
  color:#f2f4fb;
  font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','Vazirmatn',Tahoma,sans-serif;
  display:flex;align-items:center;justify-content:center;
  min-height:100vh;min-height:100dvh;padding:0 32px;text-align:center;
}
.wrap{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:18px;max-width:420px}
.brand-mark{display:flex;align-items:center;justify-content:center;animation:floaty 2.4s ease-in-out infinite}
.brand-mark img{width:120px;height:120px;border-radius:28px;overflow:hidden;display:block}
@keyframes floaty{0%,100%{transform:translateY(0) rotate(0deg)}50%{transform:translateY(-8px) rotate(4deg)}}
.title{font-size:22px;font-weight:700;line-height:1.6}
.msg{color:#9aa4c7;font-size:14px;line-height:1.9}
.secured-by{position:absolute;left:50%%;transform:translateX(-50%%);bottom:calc(18px + env(safe-area-inset-bottom,0px));
  display:flex;align-items:center;gap:7px;color:#9aa4c7;opacity:.72;direction:ltr;user-select:none;
  font-family:"Segoe UI",-apple-system,BlinkMacSystemFont,system-ui,sans-serif}
.secured-by img{width:20px;height:20px;border-radius:26%%;display:block;
  box-shadow:0 0 0 1px rgba(240,207,133,.8),0 2px 6px -2px rgba(140,10,20,.55)}
.secured-by span{font-size:11px;font-weight:500;letter-spacing:.04em;line-height:1;white-space:nowrap}
.secured-by b{font-weight:800;letter-spacing:.12em;color:#f0cf85}
@media (prefers-reduced-motion:reduce){.brand-mark{animation:none}}
"""


def render_status_page(tab_title, title, message_html):
    """صفحه‌ی کاملِ HTML. message_html باید از قبل امن/escape شده باشد (متنِ ثابتِ خودمان)."""
    return (
        "<!doctype html><html lang='fa' dir='rtl'><head><meta charset='utf-8'>"
        "<meta name='viewport' content='width=device-width,initial-scale=1,viewport-fit=cover'>"
        "<title>" + _html.escape(tab_title) + "</title>"
        "<style>" + _STYLE + "</style></head><body>"
        "<div class='wrap'>"
        "<div class='brand-mark'><img src='" + LOGO_DATA_URI + "' alt='' aria-hidden='true'></div>"
        "<div class='title'>" + _html.escape(title) + "</div>"
        "<div class='msg'>" + message_html + "</div>"
        "</div>"
        "<div class='secured-by' title='Chess Security Force'>"
        "<img src='" + LOGO_DATA_URI + "' alt='' aria-hidden='true'>"
        "<span>Secured by <b>CSF</b></span></div>"
        "</body></html>"
    )
